command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
cd ~/Upload-Assistant-wastaken
echo compose-settings:
grep -nE 'image:|container_name:|ports:|volumes:|environment:|UA_DATA_DIR|BROWSE_ROOTS|webui' docker-compose.local.yml || true
echo mounted-config:
grep -nE '"(default_trackers|multiScreens|charLimit|processLimit|qbit_|deluge_|radarr_|sonarr_)' docker-data/data/config.py | head -100 || true
echo recent-logs:
podman logs --tail 40 upload-assistant-wastaken 2>&1 || true
echo mounts:
podman inspect upload-assistant-wastaken --format '{{range .Mounts}}{{println .Source " -> " .Destination}}{{end}}' || true
REMOTE
